                + (e.from() == null ? "" : " from=" + e.from())
                + (e.to() == null ? "" : " to=" + e.to()));
    }

    @TransactionalEventListener
    public void on(SheetArchived e) {
        change(e.sheetId(), e.user(), "SHEET_ARCHIVED sheet=" + e.sheetId() + " by=" + e.user());
    }

    @TransactionalEventListener
    public void on(SheetCloned e) {
        change(e.sheetId(), e.user(), (e.to() != null ? "SHEET_CLONE_MADE" : "SHEET_CLONED") + " sheet=" + e.sheetId()
                + " by=" + e.user() + (e.to() == null ? "" : " to=" + e.to()) + (e.from() == null ? "" : " from=" + e.from()));
    }

    @TransactionalEventListener
    public void on(RoleSet e) {
        change(e.sheetId(), e.user(), "ROLE_SET sheet=" + e.sheetId() + " by=" + e.user() + " user=" + e.name() + " role=" + e.role());
    }

    @TransactionalEventListener
    public void on(SettingChanged e) {
        change(e.sheetId(), e.user(), "SETTING_CHANGED sheet=" + e.sheetId() + " by=" + e.user() + " key=" + e.key() + " value=" + e.value()
                + (e.from() == null ? "" : " from=" + e.from()));
    }

    @TransactionalEventListener
    public void on(PeriodAdded e) {
        change(e.sheetId(), e.user(), "PERIOD_ADDED sheet=" + e.sheetId() + " by=" + e.user()
                + " period=" + e.name() + " from=" + e.from() + " to=" + e.to() + (e.cap() == null ? "" : " cap=" + e.cap()));
    }

    @TransactionalEventListener
    public void on(VoidReasonAdded e) {
        change(e.sheetId(), e.user(), "VOID_REASON_ADDED sheet=" + e.sheetId() + " by=" + e.user() + " reason=" + e.reason());
    }

    @TransactionalEventListener
    public void on(TemplateSaved e) {
        change(e.sheetId(), e.user(), "TEMPLATE_SAVED sheet=" + e.sheetId() + " by=" + e.user() + " name=" + e.name()
                + " amount=" + e.amount().setScale(2, RoundingMode.HALF_UP).toPlainString() + " note=" + e.note());
